import math

class Solution:
    def normalize(self, x: list[float], eps: float) -> list[float]:
        mean=sum(x)/len(x)
        variance=sum((v-mean)**2 for v in x)/len(x)
        return [(v-mean)/math.sqrt(variance+eps) for v in x]

